<script setup lang="ts">
import {ref,watch} from 'vue';import {newKey,api,mutate,can,text,date,useTask,type DTO,type Page} from './shared';import {request,download} from '../../shared/api/client';import {useForm} from './forms';import TaskForm from './TaskForm.vue';import PageState from './PageState.vue';import Pager from './Pager.vue';
type Material=DTO<'Stage2EntryMaterialView'>|DTO<'Stage2NoteMaterialView'>|DTO<'Stage2AttachmentMaterialView'>;
const props=defineProps<{resource:DTO<'ResourceView'>}>(),{busy,error,notice,run}=useTask(),{form,open}=useForm();
const rows=ref<Material[]>([]),files=ref<DTO<'Stage2FileView'>[]>([]),page=ref(1),total=ref(0),more=ref(false),filePage=ref(1),fileTotal=ref(0),fileMore=ref(false),classification=ref('normal'),selected=ref<File>(),replaceFile=ref<DTO<'Stage2FileView'>>();let uploadKey=newKey();
async function load(){await run(async()=>{const [m,f]=await Promise.all([api.get<Page<Material>>(`/resources/${props.resource.id}/materials?page=${page.value}`),api.get<Page<DTO<'Stage2FileView'>>>(`/resources/${props.resource.id}/files?page=${filePage.value}`)]);rows.value=m.items;files.value=f.items;total.value=m.pagination.total;more.value=m.pagination.has_next;fileTotal.value=f.pagination.total;fileMore.value=f.pagination.has_next;});}
watch(()=>props.resource.id,()=>{page.value=1;filePage.value=1;void load();},{immediate:true});
function material(kind:string,row?:Material){open({title:(row?'修订':'新增')+text(kind),fields:[{key:'title',label:'标题',required:true,initial:row?.title??undefined},...(kind==='entry'?[{key:'url',label:'访问地址',type:'url',required:true,initial:row?.kind==='entry'?row.url:undefined}]:[{key:'body',label:'说明内容（禁止填秘密）',type:'textarea',required:true,max:16000,initial:row?.kind==='note'?row.body:undefined}]),{key:'classification',label:'资料可见性',initial:row?.classification??'normal',options:[{value:'normal',label:'普通'},{value:'restricted',label:'受限（资料权限）'}]}],onSubmit:async v=>{if(row)await mutate(`/materials/${row.id}`,{expected_version:row.version,kind,changes:v},'PATCH');else await mutate(`/resources/${props.resource.id}/materials`,{kind,...v});await load();}});}
async function upload(){await run(async()=>{if(!selected.value)return;const f=selected.value;if(f.size>10*1024*1024)throw new Error('附件不能超过 10 MiB');const q=new URLSearchParams({resource_id:props.resource.id,filename:f.name,classification:classification.value,...(replaceFile.value?{replaces_file_id:replaceFile.value.id,expected_version:String(replaceFile.value.version)}:{})});const file=await request<DTO<'Stage2FileView'>>('/files?'+q,{method:'POST',body:f,headers:{'Content-Type':'application/octet-stream','Idempotency-Key':uploadKey}});selected.value=undefined;replaceFile.value=undefined;uploadKey=newKey();await mutate(`/resources/${props.resource.id}/materials`,{kind:'attachment',title:file.filename,file_ref:file.id,classification:file.classification});await load();notice.value='附件已上传并登记。';});}
function endFile(f:DTO<'Stage2FileView'>){open({title:'结束附件',description:'结束后停止下载，历史记录保留。相关执行证据将需要重新核实。',fields:[{key:'reason',label:'结束原因',type:'textarea',required:true}],onSubmit:async v=>{await mutate(`/files/${f.id}/actions/end`,{expected_version:f.version,reason:v.reason});await load();}});}
</script>
<template><div><div class="mb-3 flex flex-wrap justify-between gap-2"><p class="text-xs text-gray-500">入口与说明可用于操作；附件可作为治理证据。秘密请放在凭据中。</p><div v-if="resource.capabilities.edit&&can('materials.write')" class="flex gap-2"><button class="btn-secondary" @click="material('entry')">添加入口</button><button class="btn-secondary" @click="material('note')">添加说明</button></div></div><PageState :error="error" :busy="busy" :notice="notice" @retry="load"/><article v-for="m in rows" :key="m.id" class="border-b border-gray-100 py-3"><div class="flex items-center justify-between gap-2"><h3 class="text-sm font-medium">{{m.title}} <span class="ml-1 text-[11px] font-normal text-gray-500">{{text(m.kind)}} · {{text(m.classification)}}</span></h3><button v-if="m.kind!=='attachment'&&resource.capabilities.edit&&can('materials.write')" class="btn-ghost text-xs" @click="material(m.kind,m)">修订</button></div><a v-if="m.kind==='entry'&&/^https?:\/\//.test(m.url)" :href="m.url" target="_blank" rel="noopener noreferrer" class="text-link mt-1 block break-all text-sm">{{m.url}}</a><p v-if="m.kind==='note'" class="mt-1 whitespace-pre-wrap break-words text-sm leading-6 text-gray-600">{{m.body}}</p><p class="mt-1 text-[11px] text-gray-400">{{date(m.updated_at)}}</p></article><Pager :page="page" :total="total" :more="more" @change="page=$event;load()"/><h3 class="mb-2 mt-5 text-sm font-medium">私有附件</h3><div v-if="resource.capabilities.edit&&can('materials.write')" class="mb-3 space-y-2 rounded-lg bg-gray-50 p-3"><p class="text-xs text-gray-500">仅支持 TXT、PNG、JPEG、PDF，最大 10 MiB；文件经过内容类型检查。</p><p v-if="replaceFile" class="text-xs text-amber-700">正在替换：{{replaceFile.filename}} <button @click="replaceFile=undefined">取消替换</button></p><div class="flex flex-wrap items-center gap-2"><input type="file" accept=".txt,.png,.jpg,.jpeg,.pdf" class="min-w-0 max-w-full text-xs" aria-label="选择附件" :disabled="busy" @change="selected=($event.target as HTMLInputElement).files?.[0];uploadKey=newKey()"><select v-model="classification" aria-label="附件可见性" class="feishu-input"><option value="normal">普通</option><option v-if="can('materials.restricted')" value="restricted">受限</option></select><button class="btn-secondary" :disabled="busy||!selected" @click="upload">上传并登记</button></div></div><div v-for="f in files" :key="f.id" class="flex flex-wrap items-center justify-between gap-2 border-b border-gray-100 py-2"><div><span class="text-sm">{{f.filename}}</span><p class="mt-1 text-xs text-gray-500">{{Math.ceil(f.size_bytes/1024)}} KiB · {{text(f.status)}} · {{text(f.classification)}}</p></div><div class="flex flex-wrap gap-1"><button v-if="f.status==='available'" class="btn-ghost text-xs" @click="run(()=>download(`/files/${f.id}/content`,f.filename))">下载</button><template v-if="f.status==='available'&&resource.capabilities.edit&&can('materials.write')"><button class="btn-ghost text-xs" @click="replaceFile=f">替换</button><button class="btn-ghost text-xs" @click="endFile(f)">结束</button></template></div></div><Pager :page="filePage" :total="fileTotal" :more="fileMore" @change="filePage=$event;load()"/><TaskForm v-if="form" v-bind="form" @close="form=undefined"/></div></template>
